   "uniqueItems": true,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "generatedPath",
     "generatedSha256",
     "sourcePath",
     "sourceSha256"
    ],
    "properties": {
     "generatedPath": {
      "$ref": "urn:opensip:product-v1:workflows:common#/$defs/LogicalPath"
     },
     "generatedSha256": {
